scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_291'] || []

control 'CKV_AWS_291' do
  title 'Ensure MSK nodes are private'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_msk_cluster resources that actually exist, enumerated through
    the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    Public access attaches an elastic IP to every broker, putting the Kafka
    listener directly on the internet where only the security group and the
    cluster's own authentication stand between a scanner and the topics.
    Brokers reached through the VPC keep that surface off the public network
    entirely.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_msk_cluster:
    broker_node_group_info/[0]/connectivity_info/[0]/public_access/[0]/type
    is not SERVICE_PROVIDED_EIPS
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_msk_cluster:

      resource "aws_msk_cluster" "events" {
        cluster_name           = "events"
        kafka_version          = "3.6.0"
        number_of_broker_nodes = 3

        broker_node_group_info {
          instance_type   = "kafka.m5.large"
          client_subnets  = var.private_subnet_ids
          security_groups = [aws_security_group.msk.id]

          connectivity_info {
            public_access {
              type = "DISABLED"
            }
          }

          storage_info {
            ebs_storage_info { volume_size = 100 }
          }
        }

        encryption_info {
          encryption_in_transit {
            client_broker = "TLS"
            in_cluster    = true
          }
        }
      }

    Out of band — aws_msk_cluster:

      aws kafka update-connectivity --cluster-arn <arn> --current-version <version> --connectivity-info '{"PublicAccess":{"Type":"DISABLED"}}'

    Note (aws_msk_cluster): Turning public access off releases the brokers'
    elastic IPs, so any client bootstrapping against the public endpoint must be
    moved into the VPC (or onto a VPC connection) before the update.
  FIX

  tag checkov_id:            'CKV_AWS_291'
  tag checkov_category:      'NETWORKING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'negative'
  tag tf_resources:          %w[aws_msk_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/msk_cluster#broker-node-group-info'
  tag nist:                  ['SC-7', 'SC-7 (5)']
  tag nist_r4:               ['SC-7', 'SC-7 (5)']
  tag cci:                   ['CCI-001097', 'CCI-002080']
  tag ksi:                   ['KSI-CNA-NDS']
